#include <stdio.h>
#include <stdlib.h>

typedef struct { int id; const char *name; } Item;

int cmp_by_id(const void *a, const void *b) {
    const Item *x = a, *y = b;
    return (x->id > y->id) - (x->id < y->id);
}

int main(void) {
    size_t n = 4;
    Item *arr = malloc(n * sizeof(Item));
    if (!arr) return 1;

    arr[0] = (Item){3, "gamma"};
    arr[1] = (Item){1, "alpha"};
    arr[2] = (Item){4, "delta"};
    arr[3] = (Item){2, "beta"};

    qsort(arr, n, sizeof(Item), cmp_by_id);
    for (size_t i = 0; i < n; i++) printf("%d:%s\n", arr[i].id, arr[i].name);

    free(arr); arr = NULL;
    return 0;
}
